import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Test {
  static PrintWriter writer =
      new PrintWriter(System.out);
  int R, C;
  long[][] ch = new long[61][61];
  int[] cntA = new int[61], cntB = new int[61];
  long best = Long.MAX_VALUE;
  String str;
  Map<Long, Long> cache = new HashMap<>();
  Set<Long> tried = new HashSet<>();

  public static void main(String[] args) {
    Test te = new Test();
    te.start();
    writer.flush();
  }

  static int readInt() {
    try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
      String line = br.readLine();
      return Integer.parseInt(line.trim());
    } catch (IOException e) {
      return 0;
    }
  }

  static long readLong() {
    try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
      String line = br.readLine();
      return Long.parseLong(line.trim());
    } catch (IOException e) {
      return 0L;
    }
  }

  static String readString() {
    try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
      return br.readLine().trim();
    } catch (IOException e) {
      return "";
    }
  }

  void start() {
    R = readInt();
    C = readInt();
    for (int i = 0; i <= 2 * (R + C); i++)
      for (int j = 0; j <= i; j++)
        if (j == 0 || j == i) ch[i][j] = 1;
        else ch[i][j] = ch[i - 1][j - 1] + ch[i - 1][j];
    long x = 0, y = 0;
    int v1 = R + C, v2 = R + C;
    while (v1 >= R && v2 >= R)
      if (x > y) {
        long cur = ch[v1][R] - ch[v1 - 1][R];
        long other = ch[v2][R];
        y += cur * other;
        v1--;
      } else {
        long cur = ch[v2][R] - ch[v2 - 1][R];
        long other = ch[v1][R];
        x += cur * other;
        v2--;
      }
    best = Math.abs(x - y);
    dfs(0, 0, R + C, R + C);
    str = readString();
    for (int i = 0; i < 2 * (R + C); i++) {
      cntA[i + 1] = cntA[i] + (str.charAt(i) == 'A' ? 1 : 0);
      cntB[i + 1] = cntB[i] + (str.charAt(i) == 'B' ? 1 : 0);
    }
    long ans = solve(0, 0, R + C, R + C);
    writer.println(ans);
  }
}
